function validate([accounts]) {
  if (accounts.length < 1 || accounts.length > 50) return 'accounts needs 1 to 50 customers.';
  const n = accounts[0].length;
  if (n < 1 || n > 50) return 'Each customer has 1 to 50 bank accounts.';
  if (accounts.some(row => row.length !== n)) return 'Every customer has the same number of accounts.';
  if (accounts.some(row => row.some(money => money < 1 || money > 100))) return 'Each amount is between 1 and 100.';
  return null;
}

