function maximumWealth(accounts) {
  // Total every row, sort the totals from largest to smallest, and take the first.
  const totals = accounts.map(row => row.reduce((sum, value) => sum + value, 0));
  totals.sort((a, b) => b - a);
  return totals[0];
}

